主动断开连接
若网络出现异常，通常会触发 offline 事件。此事件可通过浏览器的 API 进行监控，原生应用也能监控到该事件并将其发送至 webview。当监控到 offline 事件后，若短时间内（可设为 10 秒）网络恢复正常，Realtime SDK 能够自动重连。若 10 秒后网络依旧异常，则主动断开连接，让用户手动重连。
另外如果长时间切换至后台后再切换至前台时，可能页面会重新加载，请根据业务实际情况进行处理。
const checkNetworkStatus = () => {\n
  let timer: NodeJS.Timeout | null = null;\n
  \n
  function handleNetworkStatus() {\n
    if (!navigator.onLine) {\n
      timer = setTimeout(() => {\n
        if (!navigator.onLine) {\n
          console.log('network offline 10s');\n
          // client 为 RealtimeClient 实例\n
          client.disconnect();\n
        }\n
      }, 10 * 1000);\n
    } else {\n
      timer && clearTimeout(timer);\n
    }\n
  }\n
  // 监听 online/offline 事件\n
  window.addEventListener('online', handleNetworkStatus);\n
  window.addEventListener('offline', handleNetworkStatus);\n
};
const checkNetworkStatus = () => {
let timer: NodeJS.Timeout | null = null;
function handleNetworkStatus() {
if (!navigator.onLine) {
timer = setTimeout(() => {
if (!navigator.onLine) {
console.log('network offline 10s');
// client 为 RealtimeClient 实例
client.disconnect();
}
}, 10 * 1000);
} else {
timer && clearTimeout(timer);
}
}
// 监听 online/offline 事件
window.addEventListener('online', handleNetworkStatus);
window.addEventListener('offline', handleNetworkStatus);
};
